<?php
namespace App\Http\Controllers;
use App\Models\{Activity,ActivityType,Application,ApplicationCoordinationTask,ApplicationDocument,ApplicationFollowUp,ApplicationParticipant,Certificate,Department,Institution,Invoice,Letter,Payment,PaymentMethod,User,WorkflowTemplate};
use App\Notifications\NewApplicationNotification;
use App\Notifications\ApplicationDispositionNotification;
use App\Notifications\KamkordikCoordinationNotification;
use App\Services\{AuditService,NumberGenerator,WorkflowEngine};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Storage;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
class ApplicationController extends Controller {
 public function index(Request $r){$q=Application::with(['applicant','activityType','institution']);if($r->user()->hasRole('applicant'))$q->where('applicant_id',$r->user()->id);if($r->status)$r->status==='submitted'?$q->whereIn('status',['draft','submitted','waiting_approval']):$q->where('status',$r->status);if($r->q)$q->where(fn($x)=>$x->where('number','like','%'.$r->q.'%')->orWhere('title','like','%'.$r->q.'%'));return view('applications.index',['applications'=>$q->latest()->paginate(12)->withQueryString()]);}
 public function create(){return view('applications.form',['application'=>new Application,'types'=>ActivityType::where('active',1)->get(),'institutions'=>Institution::orderBy('name')->get(),'departments'=>Department::orderBy('name')->get()]);}
 public function store(Request $r,NumberGenerator $numbers,WorkflowEngine $workflow){$data=$this->validated($r);$documents=$data['documents']??[];unset($data['documents']);$this->resolveInstitution($data);$data['number']=$numbers->next('diklat');$data['applicant_id']=$r->user()->id;$app=Application::create($data);if($app->participant_count===1)$this->addApplicantAsParticipant($app,$r->user());$this->storeDocuments($documents,$app,$r->user()->id);$app->load(['applicant','activityType']);User::whereHas('roles',fn($query)=>$query->whereIn('slug',['super-admin','diklat-admin','diklat-head','director','deputy-director']))->get()->each->notify(new NewApplicationNotification($app));AuditService::record('diklat','create',$app,[],$app->toArray());$isInternship=$app->activityType?->name==='Magang';if($isInternship){$this->transitionModel($app,'submitted','Pengajuan Magang diteruskan ke Arsiparis.');$app->update(['submitted_at'=>now()]);$workflow->startOrResume($app);$message='Pengajuan Magang berhasil dikirim ke Arsiparis.';}else{$message='Pengajuan disimpan sebagai draf.';}if($documents)$message.=' '.count($documents).' berkas berhasil tersimpan di penyimpanan privat.';return redirect()->route('applications.show',$app)->with('success',$message);}
 public function show(Request $r,Application $application){$this->own($r,$application);$application->load(['applicant','activityType','institution','department','histories.actor','documents','participants.certificate','certificates','invoice.payments','workflowInstance.version.template','workflowInstance.version.steps','workflowInstance.tasks.step','workflowInstance.tasks.actions','coordinationTasks.sender','coordinationTasks.recipient']);$followUps=ApplicationFollowUp::where('active',true)->orderBy('sort_order')->orderBy('id')->get();$followUpLabels=ApplicationFollowUp::pluck('label','code');$paymentMethods=PaymentMethod::where('active',true)->orderBy('name')->get();$roles=$r->user()->hasRole('director')?['head-general']:['director','deputy-director'];$dispositionRecipients=User::where('active',true)->whereHas('roles',fn($query)=>$query->whereIn('slug',$roles))->with('roles')->orderBy('name')->get();$kamkordikRecipients=User::where('active',true)->whereHas('roles',fn($query)=>$query->whereIn('slug',['kamkordik-admin','kamkordik-head']))->with('roles')->orderBy('name')->get();$activeWorkflowTask=$application->workflowInstance?->tasks->first(fn($task)=>$task->status==='pending'&&($task->assignee_user_id===$r->user()->id||($task->assignee_role_slug&&$r->user()->hasRole($task->assignee_role_slug))));return view('applications.show-certificates-v3',compact('application','followUps','followUpLabels','paymentMethods','dispositionRecipients','kamkordikRecipients','activeWorkflowTask'));}
 public function edit(Request $r,Application $application){$this->own($r,$application);abort_unless(in_array($application->status,['draft','revision_required']),422);return view('applications.form',['application'=>$application,'types'=>ActivityType::where('active',1)->get(),'institutions'=>Institution::orderBy('name')->get(),'departments'=>Department::orderBy('name')->get()]);}
 public function update(Request $r,Application $application){$this->own($r,$application);$old=$application->toArray();$data=$this->validated($r);abort_if($application->workflowInstance && (int)$data['activity_type_id']!==$application->activity_type_id,422,'Kategori tidak dapat diubah setelah alur dimulai.');$documents=$data['documents']??[];unset($data['documents']);$this->resolveInstitution($data);$application->update($data);$this->storeDocuments($documents,$application,$r->user()->id);AuditService::record('diklat','update',$application,$old,$application->fresh()->toArray());$message='Pengajuan diperbarui.';if($documents)$message.=' '.count($documents).' berkas berhasil tersimpan di penyimpanan privat.';return redirect()->route('applications.show',$application)->with('success',$message);}
 public function submit(Request $r,Application $application,WorkflowEngine $workflow){$this->own($r,$application);abort_unless(in_array($application->status,['draft','revision_required']),422);$this->transitionModel($application,'submitted','Pengajuan dikirim oleh pemohon');$application->update(['submitted_at'=>now()]);$instance=$workflow->startOrResume($application);return back()->with('success',$instance?'Pengajuan dikirim dan workflow persetujuan dimulai.':'Pengajuan berhasil diajukan.');}
 public function transition(Request $r,Application $application){abort_if($application->workflowInstance()->whereIn('status',['active','revision_required'])->exists(),422,'Pengajuan ini menggunakan workflow dinamis. Tindak lanjuti melalui menu Persetujuan Saya.');$r->validate(['status'=>'required|exists:application_follow_ups,code','note'=>'nullable|string|max:1000']);abort_unless(ApplicationFollowUp::where('code',$r->status)->where('active',true)->exists(),422,'Pilihan tindak lanjut sedang tidak aktif.');$approvalStatuses=['approved','rejected','permit_issued','closed'];$permission=in_array($r->status,$approvalStatuses,true)?'diklat.approve':'diklat.verify';abort_unless($r->user()->canDo($permission),403,'Tahapan ini memerlukan kewenangan '.($permission==='diklat.approve'?'persetujuan Kepala Diklat.':'verifikasi Admin Diklat.'));$this->transitionModel($application,$r->status,$r->note);return back()->with('success','Status berhasil diperbarui.');}
 public function disposeToDirector(Request $r,Application $application){abort_unless($r->user()->canDo('diklat.verify')||$r->user()->hasRole('director'),403,'Disposisi hanya dapat dilakukan petugas berwenang.');abort_if($application->workflowInstance()->where('status','active')->exists(),422,'Pengajuan sudah memiliki tugas persetujuan yang aktif.');$data=$r->validate(['recipient_id'=>'required|exists:users,id','note'=>'nullable|string|max:1000']);$targetRoles=$r->user()->hasRole('director')?['head-general']:['director','deputy-director'];$recipient=User::where('id',$data['recipient_id'])->where('active',true)->whereHas('roles',fn($query)=>$query->whereIn('slug',$targetRoles))->firstOrFail();$template=WorkflowTemplate::where('module','diklat')->where('active',true)->firstOrFail();$version=$template->versions()->where('status','published')->latest('version_number')->firstOrFail();$step=$version->steps()->orderByDesc('position')->firstOrFail();$instance=$application->workflowInstance()->create(['workflow_version_id'=>$version->id,'current_step_id'=>$step->id,'status'=>'active','started_at'=>now()]);$instance->tasks()->create(['workflow_step_id'=>$step->id,'assignee_user_id'=>$recipient->id,'status'=>'pending','due_at'=>now()->addHours($step->sla_hours?:24)]);$position=$recipient->hasRole('head-general')?'Kepala Bagian Umum':($recipient->hasRole('director')?'Direktur':'Wakil Direktur');DB::table('application_dispositions')->insert(['application_id'=>$application->id,'destination'=>$position.': '.$recipient->name,'instruction'=>$data['note']??null,'status'=>'sent','created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);$this->transitionModel($application,'waiting_approval','Didisposisikan ke '.$position.' '.$recipient->name.'.');$recipient->notify(new ApplicationDispositionNotification($application->fresh(['applicant']),$r->user(),$data['note']??null));return back()->with('success','Disposisi berhasil dikirim ke '.$position.'.');}
 public function coordinateKamkordik(Request $r,Application $application){
  $this->own($r,$application);
  abort_unless($r->user()->canDo('diklat.verify'),403,'Koordinasi KAMKORDIK hanya dapat dibuat oleh petugas Diklat.');
  abort_if($application->usesPaymentGate() || ($application->workflowInstance?->version->steps->first()?->conditions['managed']??false),422,'Koordinasi dibuat otomatis saat tahap KAMKORDIK dimulai.');
  $data=$r->validate(['recipient_id'=>'required|exists:users,id','note'=>'required|string|max:2000']);
  $recipient=User::whereKey($data['recipient_id'])->where('active',true)->whereHas('roles',fn($query)=>$query->whereIn('slug',['kamkordik-admin','kamkordik-head']))->firstOrFail();
  $task=ApplicationCoordinationTask::create(['application_id'=>$application->id,'sender_id'=>$r->user()->id,'recipient_id'=>$recipient->id,'note'=>$data['note']]);
  $application->histories()->create(['from_status'=>$application->status,'to_status'=>$application->status,'note'=>'Koordinasi KAMKORDIK dikirim kepada '.$recipient->name.'.','changed_by'=>$r->user()->id]);
  AuditService::record('diklat','kamkordik.coordinate',$task,[],$task->toArray(),$data['note']);
  $recipient->notify(new KamkordikCoordinationNotification($task->load(['application','sender'])));
  return back()->with('success','Permintaan koordinasi berhasil dikirim ke KAMKORDIK.');
 }
 public function upload(Request $r,Application $application){
  abort_unless($r->user()->hasRole('applicant') || $r->user()->canDo('diklat.verify'),403,'Anda tidak berwenang mengunggah berkas pengajuan ini.');
  $this->own($r,$application);
  abort_unless(in_array($application->status,['draft','revision_required']),422,'Dokumen hanya dapat diunggah saat pengajuan masih draf atau memerlukan revisi.');
  $data=$r->validate([
   'documents'=>'required|array|min:1|max:20',
   'documents.*'=>'required|file|mimes:pdf,doc,docx,xls,xlsx,jpg,jpeg,png|max:10240',
  ],[
   'documents.required'=>'Pilih minimal satu berkas untuk diunggah.',
   'documents.max'=>'Maksimal 20 berkas dapat diunggah sekaligus.',
   'documents.*.mimes'=>'Format berkas harus PDF, Word, Excel, JPG, JPEG, atau PNG.',
   'documents.*.max'=>'Ukuran setiap berkas maksimal 10 MB.',
  ]);
  $this->storeDocuments($data['documents'],$application,$r->user()->id);
  $count=count($data['documents']);
  return back()->with('success',$count.' berkas berhasil tersimpan di penyimpanan privat.');
 }
 public function download(Request $r,ApplicationDocument $document){$this->own($r,$document->application);abort_unless(Storage::disk('local')->exists($document->path),404);return Storage::disk('local')->download($document->path,$document->name);}
 public function invoice(Request $r,Application $application,NumberGenerator $numbers){abort_if($application->usesPaymentGate() || ($application->workflowInstance?->version->steps->first()?->conditions['managed']??false),422,'Tagihan harus diterbitkan melalui tahap administrasi dan tagihan pada alur layanan.');$data=$r->validate(['amount'=>'required|numeric|min:0','due_date'=>'nullable|date']);$invoice=Invoice::updateOrCreate(['application_id'=>$application->id],['number'=>$application->invoice?->number??$numbers->next('invoice'),'subtotal'=>$data['amount'],'total'=>$data['amount'],'due_date'=>$data['due_date']??now()->addDays(7),'status'=>'unpaid','items'=>[['description'=>'Biaya '.$application->activityType->name,'amount'=>(float)$data['amount']]]]);$this->transitionModel($application,'waiting_payment','Invoice '.$invoice->number.' diterbitkan');return back()->with('success','Invoice berhasil diterbitkan.');}
 public function pay(Request $r,Invoice $invoice){
  $this->own($r,$invoice->application);
  $data=$r->validate(['amount'=>'required|numeric|min:1','method'=>'required|exists:payment_methods,name','reference'=>'nullable|max:100','proof'=>'required|file|mimes:pdf,jpg,jpeg,png|max:5120']);
  abort_unless(PaymentMethod::where('name',$data['method'])->where('active',true)->exists(),422,'Metode pembayaran sedang tidak aktif.');
  DB::transaction(function()use($r,$invoice,$data){
   $invoice=Invoice::lockForUpdate()->findOrFail($invoice->id);
   $application=$invoice->application;
   if($application->usesPaymentGate()){
    $instance=$application->workflowInstance;
    abort_unless($instance->status==='active'&&($instance->currentStep->conditions['payment_gate']??false),422,'Tahap pembayaran belum aktif.');
    abort_unless($invoice->status==='unpaid'&&!$invoice->payments()->where('status','waiting_verification')->exists(),422,'Bukti sudah dikirim atau pembayaran sudah diverifikasi.');
    abort_unless((float)$data['amount']===(float)$invoice->total,422,'Nominal pembayaran harus sesuai tagihan.');
   }
   $path=$data['proof']->store('payments/'.$invoice->id,'local');
   Payment::create(['invoice_id'=>$invoice->id,'amount'=>$data['amount'],'method'=>$data['method'],'reference'=>$data['reference']??null,'proof_path'=>$path,'status'=>'waiting_verification','paid_at'=>now()]);
   $invoice->update(['status'=>'waiting_verification']);
   $this->transitionModel($application,'waiting_payment_verification','Bukti pembayaran '.$invoice->number.' dikirim dan menunggu verifikasi');
   if($application->usesPaymentGate())User::whereHas('roles',fn($q)=>$q->where('slug','diklat-admin'))->where('active',true)->get()->each->notify(new \App\Notifications\ApplicationProgressNotification($application,'Bukti pembayaran '.$invoice->number.' menunggu verifikasi Diklat.'));
   AuditService::record('payment','submit',$invoice);
  });
  return back()->with('success','Bukti pembayaran dikirim dan sedang menunggu verifikasi pembayaran.');
 }
 public function paymentProof(Payment $payment){abort_unless($payment->proof_path && Storage::disk('local')->exists($payment->proof_path),404,'Bukti pembayaran tidak ditemukan.');$extension=pathinfo($payment->proof_path,PATHINFO_EXTENSION);$filename=str_replace('/','-','bukti-pembayaran-'.$payment->invoice->number.($extension?'.'.$extension:''));return Storage::disk('local')->response($payment->proof_path,$filename,['Content-Disposition'=>'inline; filename="'.$filename.'"']);}
 public function verifyPayment(Request $r,Payment $payment,WorkflowEngine $workflow){
  $gated=$payment->invoice->application->usesPaymentGate();
  $data=$r->validate(['status'=>'required|in:verified,rejected','review_note'=>[$gated&&$r->status==='rejected'?'required':'nullable','string','max:2000']]);
  DB::transaction(function()use($r,$payment,$workflow,$gated,$data){
   $invoice=Invoice::lockForUpdate()->findOrFail($payment->invoice_id);
   $payment=Payment::lockForUpdate()->findOrFail($payment->id);
   abort_unless($payment->status==='waiting_verification',422,'Pembayaran ini sudah ditinjau.');
   $application=$invoice->application;
   $task=null;
   if($gated){
    $instance=$application->workflowInstance;
    abort_unless($instance->status==='active'&&($instance->currentStep->conditions['payment_gate']??false),422,'Tahap pembayaran belum aktif.');
    $task=$instance->tasks()->where('workflow_step_id',$instance->current_step_id)->where('status','pending')->firstOrFail();
    abort_unless($workflow->canAct($r->user(),$task),403,'Verifikasi harus dilakukan petugas Diklat yang ditugaskan.');
    abort_unless((float)$payment->amount===(float)$invoice->total,422,'Nominal pembayaran harus sesuai tagihan.');
   }
   $payment->update(['status'=>$data['status'],'review_note'=>$data['review_note']??null,'verified_by'=>$r->user()->id,'verified_at'=>now()]);
   $invoice->update(['status'=>$data['status']==='verified'?'paid':'unpaid']);
   $note=$data['status']==='verified'?'Pembayaran '.$invoice->number.' telah diverifikasi':'Bukti pembayaran '.$invoice->number.' ditolak; silakan kirim ulang. '.($data['review_note']??'');
   $this->transitionModel($application,$data['status']==='verified'?'payment_verified':'waiting_payment',$note);
   if($gated){
    $application->applicant->notify(new \App\Notifications\ApplicationProgressNotification($application,$note));
    if($data['status']==='verified')$workflow->act($task,$r->user(),'approve',$note);
   }
   AuditService::record('payment','review',$payment,[],['status'=>$data['status']],$data['review_note']??null);
  });
  return back()->with('success','Pembayaran telah ditinjau.');
 }
 public function issueLetter(Request $r,Application $application){abort_unless(in_array($application->status,['approved','payment_verified','completed']),422,'Surat hanya dapat diterbitkan setelah pengajuan disetujui atau kegiatan selesai.');$data=$r->validate(['type'=>'required|in:approval,permit,rejection,completion,certificate','subject'=>'required','content'=>'required']);$sequence=Letter::whereYear('issued_at',date('Y'))->count()+1;$number='SURAT/RS/'.date('Y').'/'.str_pad($sequence,5,'0',STR_PAD_LEFT);$letter=Letter::create(['number'=>$number,'type'=>$data['type'],'letterable_type'=>$application->getMorphClass(),'letterable_id'=>$application->id,'subject'=>$data['subject'],'content'=>$data['content'],'issued_at'=>today(),'verification_token'=>Str::random(48),'status'=>'issued']);if($data['type']==='permit'){$this->transitionModel($application,'permit_issued','Surat izin '.$number.' diterbitkan');Activity::updateOrCreate(['application_id'=>$application->id],['title'=>$application->title,'start_at'=>$application->start_date->setTime(8,0),'end_at'=>$application->end_date->setTime(16,0),'location'=>$application->department?->name,'status'=>'scheduled']);}AuditService::record('document','letter.issue',$letter);return back()->with('success','Surat digital '.$number.' diterbitkan.');}
 public function verifyLetter(string $token){$letter=Letter::with('letterable')->where('verification_token',$token)->firstOrFail();return view('letters.verify',compact('letter'));}
 public function storeParticipant(Request $r,Application $application){$this->own($r,$application);$this->ensureParticipantCapacity($application);$data=$r->validate(['name'=>'required|string|max:255','identity_number'=>'nullable|string|max:100','email'=>'nullable|email|max:255','phone'=>'nullable|string|max:50']);ApplicationParticipant::create($data+['application_id'=>$application->id]);return back()->with('success','Peserta berhasil ditambahkan.');}
 public function updateParticipant(Request $r,ApplicationParticipant $participant){$this->own($r,$participant->application);abort_if($participant->certificate,422,'Peserta tidak dapat diubah karena sertifikat sudah diterbitkan.');$data=$r->validate(['name'=>'required|string|max:255','identity_number'=>'nullable|string|max:100','email'=>'nullable|email|max:255','phone'=>'nullable|string|max:50']);$participant->update($data);return back()->with('success','Data peserta berhasil diperbarui.');}
 public function destroyParticipant(Request $r,ApplicationParticipant $participant){$this->own($r,$participant->application);abort_if($participant->certificate,422,'Peserta tidak dapat dihapus karena sertifikat sudah diterbitkan.');$participant->delete();return back()->with('success','Peserta berhasil dihapus.');}
 public function issueCertificates(Request $r,Application $application,NumberGenerator $numbers){abort_unless($application->certificateEligible(),422,'Sertifikat hanya dapat diterbitkan setelah kegiatan berstatus selesai.');$participantIds=$r->validate(['participant_ids'=>'required|array|min:1','participant_ids.*'=>'integer'])['participant_ids'];$participants=$application->participants()->whereIn('id',$participantIds)->whereDoesntHave('certificate')->get();abort_if($participants->isEmpty(),422,'Peserta yang dipilih sudah memiliki sertifikat atau tidak ditemukan.');foreach($participants as $participant){$certificate=Certificate::create(['application_id'=>$application->id,'application_participant_id'=>$participant->id,'number'=>$numbers->next('certificate'),'recipient_name'=>$participant->name,'issued_at'=>today(),'issued_by'=>$r->user()->id,'verification_token'=>Str::random(48),'status'=>'issued']);AuditService::record('diklat','certificate.issue',$certificate,[],['number'=>$certificate->number],"Sertifikat diterbitkan untuk {$participant->name}");}return back()->with('success',$participants->count().' sertifikat berhasil diterbitkan.');}
 public function certificates(){return view('certificates.index',['certificates'=>Certificate::with(['application','participant'])->latest('issued_at')->paginate(15),'readyApplications'=>Application::with(['activityType','participants.certificate'])->where('status','completed')->whereDoesntHave('workflowInstance.version.steps',fn($q)=>$q->where('conditions->managed',true)->where('conditions->behavior','finish')->where('conditions->outcome','!=','certificate'))->where(fn($q)=>$q->whereDoesntHave('participants')->orWhereHas('participants',fn($p)=>$p->whereDoesntHave('certificate')))->latest()->paginate(10,['*'],'ready_page')]);}
 public function showCertificate(Request $r,Certificate $certificate){$this->own($r,$certificate->application);$certificate->load(['application.activityType','participant','issuer']);$director=DB::table('signatories')->where('active',true)->where('position','like','%Direktur%')->where(fn($q)=>$q->whereNull('valid_from')->orWhereDate('valid_from','<=',today()))->where(fn($q)=>$q->whereNull('valid_until')->orWhereDate('valid_until','>=',today()))->orderByDesc('id')->first();if($director)$certificate->setRelation('issuer',(new \App\Models\User)->forceFill(['name'=>$director->name]));return view('certificates.pretty-v2',compact('certificate'));}
 public function verifyCertificate(string $token){$certificate=Certificate::with(['application.activityType','participant'])->where('verification_token',$token)->firstOrFail();return view('certificates.verify',compact('certificate'));}
 private function validated(Request $r){return $r->validate(['activity_type_id'=>'required|exists:activity_types,id','institution_name'=>'nullable|string|max:255','department_id'=>'nullable|exists:departments,id','title'=>'required|max:255','person_in_charge'=>'nullable|max:255','participant_count'=>'required|integer|min:1','start_date'=>'required|date','end_date'=>'required|date|after_or_equal:start_date','purpose'=>'nullable','description'=>'nullable','documents'=>'nullable|array|max:20','documents.*'=>'file|mimes:pdf,doc,docx,xls,xlsx,jpg,jpeg,png|max:10240'],['documents.max'=>'Maksimal 20 berkas dapat diunggah sekaligus.']);}
 private function resolveInstitution(array &$data): void {$name=trim($data['institution_name']??'');unset($data['institution_name']);$data['institution_id']=$name===''?null:(Institution::whereRaw('lower(name) = lower(?)',[$name])->first()??Institution::create(['name'=>$name,'type'=>'Institusi Pemohon','cooperation_status'=>'pending']))->id;}
 private function storeDocuments(array $documents,Application $application,int $userId): void {foreach($documents as $file){$path=$file->store('applications/'.$application->id,'local');ApplicationDocument::create(['application_id'=>$application->id,'name'=>Str::limit($file->getClientOriginalName(),150,''),'path'=>$path,'mime'=>$file->getMimeType(),'size'=>$file->getSize(),'uploaded_by'=>$userId]);}}
 private function addApplicantAsParticipant(Application $application,User $user): void {ApplicationParticipant::firstOrCreate(['application_id'=>$application->id,'email'=>$user->email],['name'=>$user->name,'identity_number'=>$user->nik,'phone'=>$user->phone]);}
 private function ensureParticipantCapacity(Application $application): void {abort_unless($application->status!=='closed',422,'Peserta tidak dapat ditambah setelah pengajuan ditutup.');abort_if($application->participants()->count()>=$application->participant_count,422,'Jumlah peserta sudah memenuhi kuota pengajuan.');}
 private function own(Request $r,Application $a){if($r->user()->hasRole('applicant'))abort_unless($a->applicant_id===$r->user()->id,403);}
 private function transitionModel(Application $a,string $to,?string $note){$from=$a->status;$a->update(['status'=>$to]);$a->histories()->create(['from_status'=>$from,'to_status'=>$to,'note'=>$note,'changed_by'=>auth()->id()]);AuditService::record('diklat','status_change',$a,['status'=>$from],['status'=>$to],$note);}
}
